-- Identity columns can coexist with other constraints in either order.
CREATE TABLE invoice_batches (id bigint GENERATED ALWAYS AS IDENTITY (START WITH 10 INCREMENT BY 5) PRIMARY KEY, sequence_no int GENERATED BY DEFAULT AS IDENTITY NOT NULL, revision int NOT NULL GENERATED ALWAYS AS IDENTITY);

-- Combine generated calendar rows with labels and retain row ordinality.
SELECT r.day_no, r.label, r.ordinal FROM ROWS FROM (generate_series(1,3), unnest(ARRAY['open','pending','closed'])) WITH ORDINALITY AS r(day_no, label, ordinal);

-- Select a two-dimensional report cell and a window of daily counts.
SELECT ARRAY[[10,20],[30,40]][1][2] AS report_cell, ARRAY[5,8,13][1:2] AS first_days;

-- Combine regional subtotals and all-region totals in a revenue report.
SELECT department, region, SUM(amount) FROM monthly_sales GROUP BY GROUPING SETS ((department), ROLLUP(region), CUBE(department, region), ());

-- Nest a grouping-set list inside a report's grouping sets.
SELECT department, region, SUM(amount) FROM monthly_sales GROUP BY GROUPING SETS (GROUPING SETS ((department), (region)), ());
